oxy_webhelp_navlinks = {"retention_management-d39536e7605":{"topics":[{"title":"Snapshot types","shortdesc":"<p class=\"shortdesc\">Information about types of the snapshots. Each snapshot is a fully functional,         current copy of the source object.<\/p>","href":"saas\/snapshots_types.html","attributes":{"data-id":"snapshots_types"},"menu":{"hasChildren":false},"tocID":"snapshots_types-d39536e7616","topics":[]},{"title":"On-demand snapshot retention options","shortdesc":"<p class=\"shortdesc\">When you take an on-demand snapshot, you can choose the retention period by selecting         an SLA Domain, by retaining the snapshot according to the SLA Domain currently assigned to         the object, or by retaining the snapshot forever.<\/p>","href":"saas\/on_demand_snapshot_retention_options.html","attributes":{"data-id":"on_demand_snapshot_retention_options"},"menu":{"hasChildren":false},"tocID":"on_demand_snapshot_retention_options-d39536e7627","topics":[]},{"title":"Object filters for snapshot retention","shortdesc":"<p class=\"shortdesc\">Information about the filters that you can apply to the objects on the Snapshot         Retention page. These filters are available on the Data Center and Cloud tabs of the         Snapshot Retention page.<\/p>","href":"saas\/object_filters_snapshot_retention.html","attributes":{"data-id":"object_filters_snapshot_retention"},"menu":{"hasChildren":false},"tocID":"object_filters_snapshot_retention-d39536e7638","topics":[]},{"title":"Snapshot expiration behavior","shortdesc":"<p class=\"shortdesc\">Rubrik expires a snapshot when its retention period ends. The retention period depends         on the snapshot type and on the SLA Domain.<\/p>","href":"saas\/snapshot_expiry.html","attributes":{"data-id":"snapshot_expiry"},"menu":{"hasChildren":false},"tocID":"snapshot_expiry-d39536e7649","topics":[]},{"title":"Snapshot frequency mapping","shortdesc":"<p class=\"shortdesc\">Rubrik maps each policy-based snapshot to a frequency in the SLA Domain when it takes         the snapshot. The frequency determines the retention period of the snapshot and does not         change afterward.<\/p>","href":"saas\/snapshot_frequency_mapping.html","attributes":{"data-id":"snapshot_frequency_mapping"},"menu":{"hasChildren":false},"tocID":"snapshot_frequency_mapping-d39536e7660","topics":[]},{"title":"Granular snapshot deletion","shortdesc":"<p class=\"shortdesc\">You can delete snapshot copies from individual locations without changing the SLA         Domain or retention of the snapshot.<\/p>","href":"saas\/granular_snapshot_deletion.html","attributes":{"data-id":"granular_snapshot_deletion"},"menu":{"hasChildren":false},"tocID":"granular_snapshot_deletion-d39536e7671","topics":[]},{"title":"Changing the retention period of a snapshot","shortdesc":"<p class=\"shortdesc\">Change the retention period of a snapshot of data center, cloud native, or <span class=\"ph\">NAS CD<\/span> workload objects.<\/p>","href":"saas\/changing_retention_period_snapshot.html","attributes":{"data-id":"changing_retention_period_snapshot"},"menu":{"hasChildren":false},"tocID":"changing_retention_period_snapshot-d39536e7682","topics":[]},{"title":"Changing the retention period of multiple objects","shortdesc":"<p class=\"shortdesc\">Change the retention period of all the snapshots of an object or multiple objects         associated with data center or cloud native workloads. <\/p>","href":"saas\/changing_retention_multiple_objects.html","attributes":{"data-id":"changing_retention_multiple_objects"},"menu":{"hasChildren":false},"tocID":"changing_retention_multiple_objects-d39536e7696","topics":[]},{"title":"Deleting a snapshot","shortdesc":"<p class=\"shortdesc\">Delete a specific snapshot or multiple snapshots of a workload object or multiple         objects when you want to identify unmanaged snapshots and perform cleanup activity to reduce         cloud costs, respectively.<\/p>","href":"saas\/deleting_snapshot.html","attributes":{"data-id":"deleting_snapshot"},"menu":{"hasChildren":false},"tocID":"deleting_snapshot-d39536e7707","topics":[]},{"title":"Cluster storage reclamation","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> displays notifications when CDM clusters are running low on         storage and provides a workflow to reclaim space by removing relic, downloaded, protected,         or unprotected snapshots.<\/p>","href":"saas\/cluster_storage_reclamation.html","attributes":{"data-id":"cluster_storage_reclamation"},"menu":{"hasChildren":false},"tocID":"cluster_storage_reclamation-d39536e7718","next":"cluster_storage_reclamation-d39536e7718"},{"title":"Searching for an object on the Snapshot Retention page","shortdesc":"<p class=\"shortdesc\">Search for a specific object by object name on the Snapshot Retention         page.<\/p>","href":"saas\/searching_object_on_snapshot_retention_page.html","attributes":{"data-id":"search_object_on_snapshot_retention_page"},"menu":{"hasChildren":false},"tocID":"search_object_on_snapshot_retention_page-d39536e7743","topics":[]},{"title":"Reader cluster workload refresh","shortdesc":"<p class=\"shortdesc\">Refreshing workloads on the reader Rubrik cluster synchronizes the recovery view of         the reader cluster with the contents of the archival location.<\/p>","href":"archival\/reader_cluster_workload_refresh.html","attributes":{"data-id":"reader_cluster_workload_refresh"},"menu":{"hasChildren":false},"tocID":"reader_cluster_workload_refresh-d39536e7754","topics":[]},{"title":"Refreshing reader location objects","shortdesc":"<p class=\"shortdesc\">Use <span class=\"ph\">RSC<\/span> to update a reader cluster with the latest snapshot         metadata.<\/p>","href":"saas\/rbk_refreshing_reader_location_objects.html","attributes":{"data-id":"rbk_refreshing_reader_location_objects"},"menu":{"hasChildren":false},"tocID":"rbk_refreshing_reader_location_objects-d39536e7765","topics":[]},{"title":"Relic data sources","shortdesc":"<p class=\"shortdesc\">A data source is designated as a relic if it is managed by, but is no longer         accessible to the Rubrik cluster.<\/p>","href":"saas\/cdm_relic_data_sources.html","attributes":{"data-id":"cdm_relic_data_sources"},"menu":{"hasChildren":false},"tocID":"cdm_relic_data_sources-d39536e7779","topics":[]},{"title":"Intelligent Data Lock","shortdesc":"<p class=\"shortdesc\">Intelligent Data Lock is a feature that protects your account from malicious activity         by delaying the deletion of the snapshots of the data sources backed up by Rubrik         clusters.<\/p>","href":"common\/intelligent_data_lock.html","attributes":{"data-id":"intelligent_data_lock"},"menu":{"hasChildren":false},"tocID":"intelligent_data_lock-d39536e7790","topics":[]}]}};